glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TINT
in vec4 a_color0;
#endif
#if USE_TEXTURE
#endif
in vec2 a_uv0;
out vec2 v_uv0;
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  v_uv0 = a_uv0;
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
in vec4 v_color;
in vec2 v_uv0;
uniform sampler2D texture;
#if SHOW_OUT_LINE
uniform Outline {
  vec4 outlineColor;
  float outlineWidth;
};
float getBgAlpha() {
  float outlineWidth1 = outlineWidth;
  vec4 color_up = texture(texture, v_uv0 + vec2(0, outlineWidth1));
  vec4 color_down = texture(texture, v_uv0 - vec2(0, outlineWidth1));
  vec4 color_left = texture(texture, v_uv0 - vec2(outlineWidth1, 0));
  vec4 color_right = texture(texture, v_uv0 + vec2(outlineWidth1, 0));
  vec4 color_up_left = texture(texture, v_uv0 + vec2(outlineWidth1, -outlineWidth1));
  vec4 color_up_right = texture(texture, v_uv0 + vec2(outlineWidth1, outlineWidth1));
  vec4 color_down_left = texture(texture, v_uv0 + vec2(-outlineWidth1, -outlineWidth1));
  vec4 color_down_right = texture(texture, v_uv0 + vec2(-outlineWidth1, outlineWidth1));
  float total = color_right.a + color_left.a + color_down.a + color_up.a + color_up_left.a + color_up_right.a + color_down_left.a + color_down_right.a;
  return clamp(total, 0.0, 1.0);
}
#endif
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  o *= texture(texture, v_uv0);
  gl_FragColor = o;
  #if SHOW_OUT_LINE
    vec4 color_dest = outlineColor * getBgAlpha();
    vec4 color_src = o;
    gl_FragColor = color_src * color_src.a + color_dest * (1.0 - color_src.a);
  #endif
}

